      "tmdb_title_en": "The Phantom of the Opera at the Royal Albert Hall",
      "tmdb_title_zh": "歌剧魅影：25周年纪念演出",
      "tmdb_release_date": "2011-09-27",
      "imdb_url": "https://www.imdb.com/title/tt2077886/"
